def namespace(file, prelude):
    ns = {}
    exec('from symox import *', ns)
    ns.update(risch_integrate=risch_integrate, NonElementaryIntegral=NonElementaryIntegral,
              manualintegrate=manualintegrate, heurisch=heurisch,
              heurisch_wrapper=heurisch_wrapper)
    for statement in MODULES[file] + list(prelude):
        exec(statement, ns)
    return ns


@pytest.mark.parametrize('file,prelude,expr,kind,text', CASES,
                         ids=['%s:%s' % (c[0][5:-3], c[2]) for c in CASES])
def test_reference_integration_examples(file, prelude, expr, kind, text):
    try:
        result = eval(expr, namespace(file, prelude))
    except Exception as error:
        assert ('EXC:' + type(error).__name__, str(error)) == (kind, text)
        return
    kind_of = 'tuple' if isinstance(result, tuple) else type(result).__name__
    assert (kind_of, str(result)) == (kind, text)
